package com.odin.odin.controller;
import com.odin.odin.model.Anexos; import com.odin.odin.repository.AnexosRepository; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/anexos") public class AnexosController { private final AnexosRepository repo; public AnexosController(AnexosRepository repo){this.repo=repo;} @GetMapping("/radicado/{id}") public List<Anexos> porRadicado(@PathVariable Long id){return repo.findByIdRadicadoOrderByIdAnexoDesc(id);} @PostMapping public ResponseEntity<Anexos> crear(@RequestBody Anexos a){ if(a.getIdRadicado()==null||a.getDescripcion()==null||a.getDescripcion().isBlank()||a.getArchivo()==null||a.getArchivo().isBlank()) return ResponseEntity.badRequest().build(); return ResponseEntity.ok(repo.save(a)); } @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){ if(!repo.existsById(id)) return ResponseEntity.notFound().build(); repo.deleteById(id); return ResponseEntity.noContent().build(); } }
